<script setup lang="ts">
import { watch } from 'vue'; import AdminFilters from '@/components/admin/AdminFilters.vue'; import AdminCourierTable from '@/components/admin/AdminCourierTable.vue'; import PageHeader from '@/components/common/PageHeader.vue'; import { useAdminCouriers } from '@/composables/useAdminCouriers'; import { useAdminListQuery } from '@/composables/useAdminListQuery'
const options=[{label:'在职',value:'ACTIVE'},{label:'暂停',value:'SUSPENDED'},{label:'离职',value:'LEFT'}];const {route,keyword,status,page,search,reset,setPage}=useAdminListQuery('employmentStatus');const {records,total,loading,errorMessage,load}=useAdminCouriers();function refresh(){return load({page:page.value,pageSize:10,keyword:String(route.query.keyword||''),employmentStatus:String(route.query.employmentStatus||'')})}watch(()=>route.query,refresh,{immediate:true})
</script>
<template><div><PageHeader title="配送员管理" description="查看配送员档案、接单状态与履约效率。" refreshable :refreshing="loading" @refresh="refresh"/><AdminFilters v-model:keyword="keyword" v-model:status="status" placeholder="工号、姓名或手机号" status-label="在职状态" :options="options" :loading="loading" @search="search" @reset="reset"/><el-alert v-if="errorMessage" :title="errorMessage" type="error" :closable="false" show-icon/><section class="admin-list-card"><AdminCourierTable :couriers="records" :loading="loading"/><el-pagination v-if="total>10" background layout="prev, pager, next, total" :current-page="page" :page-size="10" :total="total" @current-change="setPage"/></section></div></template>
